let zNG=[{id:"cottage",tag:"Домофония · R-Lock",fromReview:!0,title:"Домофония для коттеджа",desc:"Схема из обзора решений: основная станция вызова у входной двери, дополнительные станции на калитке, в гараже или мастерской, PoE-коммутатор и основное с дополнительными абонентскими устройствами. Мониторы с Wi-Fi работают с мобильным приложением для жильцов.",img:"/solutions/solutions-cottage.png",alt:"Коттедж с IP-домофонией: станция вызова, монитор, PoE-коммутатор",items:[{sku:"SC-INT-D100-1-MSB",label:"Основная станция вызова"},{sku:"SC-INT-D100-2-MSB",label:"Доп. станция вызова (калитка, гараж)"},{sku:"SC-INT-V007-2-LWB",label:'Абонентский монитор 7", Wi-Fi, PoE'},{sku:"SC-8GP-120-2G(A)",label:"PoE-коммутатор 8 портов, 120 Вт"},{sku:"RL-EM280-L0S",label:"Электромагнитный замок R-Lock"},{sku:"RL-DCM-EN2-00S",label:"Доводчик двери R-Lock"}],links:[{href:"#/intercom",label:"Домофонная система"},{href:"#/rlock",label:"Замки и доводчики"}]},{id:"mkd",tag:"Домофония · SC-Box",fromReview:!0,title:"Домофония для квартир и ЖК",desc:"Схема из обзора решений: многоабонентские станции вызова у входов зданий (UTP + RVV на электрозамки), этажные PoE-коммутаторы и ядро LAN, абонентские устройства в квартирах, терминал консьержа, IP-камеры и CMS, мобильное приложение для жильцов.",img:"/solutions/solutions-apartment.png",alt:"Многоквартирный дом: станции вызова, PoE-коммутаторы, терминал консьержа",items:[{sku:"SC-INT-D004-2-MFB",label:"Многоабонентская панель (4 аб.)"},{sku:"SC-INT-D008-1-MFB",label:"Многоабонентская панель (8 аб.)"},{sku:"SC-INT-V007-2-LWB",label:'Мониторы в квартирах 7"'},{sku:"SC-INT-V010-1-AXB",label:'Терминал консьержа 10", Android'},{sku:"SC-L2-24GP-385-4G(A)",label:"Управляемый PoE-коммутатор 24"},{sku:"SC-Box-8GP-240-2G-UPS(A)",label:"Уличный узел коммутации с ИБП"}],links:[{href:"#/intercom",label:"Домофонная система"},{href:"#/nodes",label:"Узлы коммутации"}]},{id:"poe-video",tag:"Коммутаторы · PoE",fromReview:!1,title:"PoE-видеонаблюдение на коммутаторах SpaceCam",desc:"Дополнение к схеме обзора с IP-камерами и CMS: камеры получают питание и передают данные по одному кабелю на PoE-коммутаторы SpaceCam. Управляемые L2/L3 выделяют VLAN видеонаблюдения, этажные узлы агрегируются по оптике SFP в ядро сети.",img:"/solutions/solutions-poe-network.png",alt:"PoE-коммутатор с подключёнными IP-камерами и монитором",items:[{sku:"SC-16GP-285-2G(A)",label:"Неуправляемый PoE, 16 портов"},{sku:"SC-L2-24GP-385-4G(A)",label:"Управляемый PoE 24×G + 4×SFP"},{sku:"SC-L2-48GP-680-6XG(A)",label:"Агрегация: 48 PoE + 6×SFP+"},{sku:"SC-Box-8GP-240-2G-UPS(A)",label:"Уличный узел с ИБП"}],links:[{href:"#/switches",label:"Коммутаторы"},{href:"#/nodes",label:"Узлы коммутации"}]},{id:"sc-box",tag:"Узлы коммутации · IP66",fromReview:!1,title:"Уличные узлы коммутации SC-Box",desc:"Дополнение к уличной части схемы: всепогодные шкафы SC-Box со встроенным коммутатором PoE, ИБП и терморегулированием. Питание и защита камер, домофонии и точек доступа на въездных группах, паркингах и КПП — в том числе в промышленном исполнении до −40 °C.",img:"/solutions/solutions-sc-box.png",alt:"Всепогодный шкаф SC-Box со станцией вызова и купольной камерой",items:[{sku:"SC-Box-L2-4GP-120-2G-UPS(A)",label:"SC-Box 4×PoE, 120 Вт, ИБП"},{sku:"SC-Box-L2-8GP-240-2G-UPS(A)",label:"SC-Box 8×PoE, 240 Вт, ИБП"},{sku:"SC-Box-L2-16GP-480-2G-UPS(A)",label:"SC-Box 16×PoE, 480 Вт, ИБП"},{sku:"SC-I-L2-8GP-240-2G(A)",label:"Промышленный коммутатор −40…+85 °C"}],links:[{href:"#/nodes",label:"Узлы коммутации"},{href:"#/switches",label:"Коммутаторы"}]},{id:"rlock",tag:"СКУД · R-Lock",fromReview:!1,title:"СКУД на электромагнитных замках R-Lock",desc:"Дополнение к точке прохода на схеме обзора: электромагнитный замок, доводчик и кнопка выхода. Замок открывается со станции вызова домофонии или контроллера СКУД — входная группа закрывается в единой сети с видеонаблюдением.",img:"/solutions/solutions-access.png",alt:"Дверь с электромагнитным замком, доводчиком и кнопкой выхода",items:[{sku:"RL-EM180-L0S",label:"Электромагнитный замок 180 кг"},{sku:"RL-EM280-L0S",label:"Электромагнитный замок 280 кг"},{sku:"RL-DCM-EN2-00S",label:"Доводчик двери EN2"}],links:[{href:"#/rlock",label:"Замки и доводчики"},{href:"#/intercom",label:"Домофонная система"}]},{id:"complex",tag:"Комплексное решение",fromReview:!1,title:"Единая сеть безопасности объекта",desc:"Обобщение обеих схем обзора: домофония, видеонаблюдение, СКУД и PoE-инфраструктура в одной сети — от абонентского монитора и замка до уличного узла коммутации с ИБП. Этажные PoE-узлы агрегируются в ядро, уличные сегменты — на SC-Box и промышленных коммутаторах SC-I.",img:"/solutions/solutions-complex.png",alt:"Жилой комплекс с единой сетью: SC-Box, камеры, домофония, замки",items:[{sku:"SC-Box-L2-16GP-480-2G-UPS(A)",label:"Агрегация улицы: SC-Box 16×PoE"},{sku:"SC-L2-48GP-680-6XG(A)",label:"Ядро сети: 48 PoE + 6×SFP+"},{sku:"SC-I-L2-16GP-380-4G(A)",label:"Промышленный сегмент"},{sku:"SC-INT-D008-1-MFB",label:"Домофония: панели на 8 абонентов"},{sku:"SC-INT-V010-1-AWB",label:'Мониторы 10", Android, Wi-Fi'}],links:[{href:"#/intercom",label:"Домофонная система"},{href:"#/switches",label:"Коммутаторы"},{href:"#/nodes",label:"Узлы коммутации"},{href:"#/rlock",label:"Замки и доводчики"}]}]
